package io.lumine.mythic.lib.skill.parameter.value; import net.minecraft.server.network.ServerPlayerEntity; public class LinearScalingFormula implements ScalingFormula { private final double base,perLevel,min,max; public LinearScalingFormula(double base,double perLevel){this(base,perLevel,-Double.MAX_VALUE,Double.MAX_VALUE);} public LinearScalingFormula(double base,double perLevel,double min,double max){this.base=base;this.perLevel=perLevel;this.min=min;this.max=max;} public double evaluate(int level,ServerPlayerEntity player){return Math.max(min,Math.min(max,base+Math.max(0,level-1)*perLevel));} public boolean isInteger(){return base==Math.rint(base)&&perLevel==Math.rint(perLevel);} }
